from pathlib import Path
p=Path('docs/specs/prd/PRD-001.md')
print(f'FILE: {p}\\n'+(p.read_text() if p.exists() else 'MISSING'))
for folder,pattern in [('arch','ARCH-*.md'),('adr','ADR-*.md')]:
